#!/usr/bin/env node
// Git merge driver for the Lingui catalogs (`src/locales/*/messages.po`).
//
// The catalogs are generated by `lingui extract` and sorted by message, so two
// branches that each add a string almost always insert next to each other and
// git's line merge reports a conflict that has nothing to decide. This driver
// merges entry by entry instead: the union of both sides' entries, keyed by
// msgctxt + msgid, written back in the order `lingui extract` uses.
//
// Per entry it is a three-way merge of two parts:
// - the `#` comment lines (source references, placeholder comments) as a set:
//   a line either side added is kept, a line either side removed is dropped;
// - the msgstr: a side that left it unchanged takes the other side's, an empty
//   one yields to a non-empty one, and two different edits of the same msgstr
//   are the only real conflict. Those entries are written with conflict
//   markers around both sides' versions and the driver exits 1, so git leaves
//   the file conflicted.
// An entry left with no `#:` reference is dropped: `lingui extract --clean`
// never writes one, so it is a message neither side uses any more.
//
// The merged catalog is only as right as the union. `pnpm i18n:check`
// re-extracts from the merged source and fails on any difference, so run it
// after a merge that touched the catalogs; CI runs it on every PR.
//
// Anything this parser does not recognise (a catalog that already carries
// conflict markers, a hand edit in another layout) falls back to git's own
// line merge, so the driver never resolves less than plain git would.
//
// Usage:
//   node scripts/merge-po.mjs --install                 register the driver in this repository's git config
//   node scripts/merge-po.mjs <base> <ours> <theirs> [marker-size] [path]   (run by git; writes <ours>)

import { execFileSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const DRIVER = "lingui-po";
// Git runs the driver from the top of the worktree. A branch from before this
// script existed has no copy of it, so the registered command falls back to
// git's own line merge there instead of failing every catalog merge.
const DRIVER_COMMAND = "if [ -f scripts/merge-po.mjs ]; then node scripts/merge-po.mjs %O %A %B %L %P; "
  + "else git merge-file -L ours -L base -L theirs --marker-size=%L %A %O %B; fi";

const args = process.argv.slice(2);
if (args[0] === "--install") {
  execFileSync("git", ["config", `merge.${DRIVER}.name`, "Lingui catalog union (scripts/merge-po.mjs)"]);
  execFileSync("git", ["config", `merge.${DRIVER}.driver`, DRIVER_COMMAND]);
  console.log(`Registered the ${DRIVER} merge driver for src/locales/**/*.po (.gitattributes).`);
  process.exit(0);
}
if (args.length < 3) {
  console.error("usage: merge-po.mjs --install | <base> <ours> <theirs> [marker-size] [path]");
  process.exit(2);
}

const [basePath, oursPath, theirsPath, markerArg, label = "messages.po"] = args;
const markerSize = Number(markerArg) > 0 ? Number(markerArg) : 7;

const read = (file) => readFileSync(file, "utf8");
const catalogs = [basePath, oursPath, theirsPath].map((file) => parseCatalog(read(file)));
if (catalogs.includes(null)) {
  // Plain git merge into <ours>; its exit status is the conflict count.
  const result = spawnSync("git", [
    "merge-file", "-L", "ours", "-L", "base", "-L", "theirs", `--marker-size=${markerSize}`,
    oursPath, basePath, theirsPath,
  ], { stdio: "inherit" });
  process.exit(result.status === 0 ? 0 : 1);
}

const [base, ours, theirs] = catalogs;
const keys = new Set([...ours.keys(), ...theirs.keys(), ...base.keys()]);
const merged = [];
const conflicts = [];
for (const key of keys) {
  const entry = mergeEntry(base.get(key), ours.get(key), theirs.get(key));
  if (entry === null) continue;
  if (entry.conflict) conflicts.push(entry);
  merged.push(entry);
}

// `lingui extract` (orderBy "message", @lingui/cli's catalog.js) sorts by
// message, then context, with an en-US collator, header first.
const collator = new Intl.Collator("en-US");
merged.sort((a, b) => Number(b.header) - Number(a.header)
  || collator.compare(a.msgid, b.msgid)
  || collator.compare(a.msgctxt, b.msgctxt)
  || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));

const marker = (char) => char.repeat(markerSize);
const blocks = merged.map((entry) => entry.conflict
  ? [`${marker("<")} ours`, entry.ours, marker("="), entry.theirs, `${marker(">")} theirs`].join("\n")
  : entry.text);
writeFileSync(oursPath, `${blocks.join("\n\n")}\n`);

if (conflicts.length > 0) {
  console.error(`merge-po: ${conflicts.length} msgstr edited differently on both sides in ${label}:`);
  for (const entry of conflicts) console.error(`  msgid ${JSON.stringify(entry.msgid)}`);
  process.exit(1);
}

// Returns Map<key, entry>, or null when the text is not a catalog in the
// layout `lingui extract` writes: blank-line-separated entries of `#` comment
// lines, then msgctxt/msgid, then msgstr, with quoted continuation lines.
function parseCatalog(text) {
  const entries = new Map();
  const body = text.replace(/\r\n/g, "\n").replace(/\n+$/, "");
  if (body.trim() === "") return entries;
  for (const block of body.split(/\n\n+/)) {
    const lines = block.split("\n");
    const comments = [];
    let index = 0;
    while (index < lines.length && lines[index].startsWith("#")) comments.push(lines[index++]);
    const keyLines = [];
    while (index < lines.length && /^(msgctxt|msgid|msgid_plural) "|^"/.test(lines[index])) keyLines.push(lines[index++]);
    const msgstr = lines.slice(index);
    if (!keyLines.some((line) => line.startsWith("msgid "))
      || msgstr.length === 0
      || !msgstr[0].startsWith("msgstr")
      || msgstr.some((line) => !/^(msgstr(\[\d+\])? "|")/.test(line))) {
      return null;
    }
    const key = keyLines.join("\n");
    if (entries.has(key)) return null;
    const msgid = poString(keyLines, "msgid");
    const msgctxt = poString(keyLines, "msgctxt");
    entries.set(key, {
      key,
      msgid,
      msgctxt,
      header: msgid === "" && msgctxt === "",
      comments,
      msgstr: msgstr.join("\n"),
    });
  }
  return entries;
}

// The unescaped value of a keyword's string, joined across continuation lines.
function poString(lines, keyword) {
  const start = lines.findIndex((line) => line.startsWith(`${keyword} "`));
  if (start === -1) return "";
  let value = unquote(lines[start].slice(keyword.length + 1));
  for (let index = start + 1; index < lines.length && lines[index].startsWith("\""); index++) {
    value += unquote(lines[index]);
  }
  return value;
}

function unquote(quoted) {
  const escapes = { n: "\n", t: "\t", r: "\r" };
  return quoted.slice(1, -1).replace(/\\(.)/g, (_, char) => escapes[char] ?? char);
}

function mergeEntry(base, ours, theirs) {
  const any = ours ?? theirs ?? base;
  const comments = mergeLines(base?.comments ?? [], ours?.comments ?? [], theirs?.comments ?? []);
  if (!any.header && !comments.some((line) => line.startsWith("#:"))) return null;

  const [b, o, t] = [base?.msgstr, ours?.msgstr, theirs?.msgstr];
  let msgstr;
  let conflict = false;
  if (o === t) msgstr = o;
  else if (b === o) msgstr = t;
  else if (b === t) msgstr = o;
  else if (o === undefined || isEmpty(o)) msgstr = t;
  else if (t === undefined || isEmpty(t)) msgstr = o;
  else conflict = true;
  // The side whose msgstr won may have deleted the entry while the other side
  // still references it; keep the surviving text.
  msgstr ??= t ?? o ?? b;

  const text = (entryMsgstr, entryComments = comments) => [...entryComments, any.key, entryMsgstr].join("\n");
  return {
    key: any.key,
    msgid: any.msgid,
    msgctxt: any.msgctxt,
    header: any.header,
    conflict,
    text: conflict ? undefined : text(msgstr),
    ours: conflict ? text(o) : undefined,
    theirs: conflict ? text(t) : undefined,
  };
}

function isEmpty(msgstr) {
  return /^msgstr ""$/.test(msgstr);
}

// Three-way merge of a set of comment lines, written in the section order
// Lingui uses (translator, extracted, references, flags) with references
// sorted, as `lingui extract` writes them.
function mergeLines(base, ours, theirs) {
  const removed = new Set([
    ...base.filter((line) => !ours.includes(line)),
    ...base.filter((line) => !theirs.includes(line)),
  ]);
  const lines = [...new Set([...ours, ...theirs])].filter((line) => !removed.has(line));
  const rank = (line) => ["# ", "#.", "#:", "#,", "#|"].findIndex((prefix) => line.startsWith(prefix));
  return lines
    .map((line, index) => ({ line, index }))
    .sort((a, b) => rank(a.line) - rank(b.line)
      || (a.line.startsWith("#:") && b.line.startsWith("#:")
        ? (a.line < b.line ? -1 : a.line > b.line ? 1 : 0)
        : a.index - b.index))
    .map(({ line }) => line);
}
